INSERT OR IGNORE INTO exercises (exercise_name, exercise_description, targeted_muscles, is_machine) VALUES
('Barbell Back Squat', 'Place barbell across upper traps, brace core, and squat until thighs are at least parallel to the floor.', 'Quadriceps', 0),
('Leg Press', 'Sit with back flat against the pad, place feet shoulder-width apart on the sled, and press without locking knees.', 'Quadriceps', 1),
('Leg Extension', 'Adjust pad above ankles, grip side handles, and extend legs fully while squeezing the quads at the top.', 'Quadriceps', 1),
('Bulgarian Split Squat', 'Rest rear foot on a bench behind you, hold dumbbells at sides, and lower until front thigh is parallel.', 'Quadriceps', 0),
('Romanian Deadlift', 'Hold barbell with a slight knee bend, hinge at the hips while keeping back flat, and lower until hamstring stretch.', 'Hamstrings', 0),
('Lying Leg Curl', 'Lie face down on the bench, align knees with the pivot point, and curl the padded lever toward your glutes.', 'Hamstrings', 1),
('Seated Leg Curl', 'Lock thigh pad snugly over quads, keep back against the seat, and flex knees to pull the lever down.', 'Hamstrings', 1),
('Barbell Hip Thrust', 'Rest upper back on a bench with a padded barbell across hips, drive through heels, and squeeze glutes at lockout.', 'Glutes', 0),
('Cable Glute Kickback', 'Attach ankle cuff to a low pulley, brace core, and extend leg straight back without arching the lower back.', 'Glutes', 1),
('Standing Calf Raise', 'Stand with balls of feet on the edge of the platform, lower heels for a full stretch, and press up onto toes.', 'Calves', 1),
('Seated Calf Raise', 'Position knee pad over lower thighs, release safety lever, and raise heels as high as possible.', 'Calves', 1),
('Conventional Deadlift', 'Stand with midfoot under the barbell, grip outside knees, flatten back, and drive hips forward to stand.', 'Back', 0),
('Lat Pulldown', 'Grip bar wider than shoulders, lean back slightly, and pull bar down to upper chest while driving elbows down.', 'Back', 1),
('Seated Cable Row', 'Sit with knees slightly bent, keep torso upright, and pull handle to lower abdomen while squeezing shoulder blades.', 'Back', 1),
('Pull-Up', 'Hang from bar with an overhand grip wider than shoulders and pull chin over the bar without swinging.', 'Back', 0),
('Bent-Over Barbell Row', 'Hinge torso to roughly 45 degrees, keep spine neutral, and row barbell toward your lower ribcage.', 'Back', 0),
('Chest-Supported Machine Row', 'Press chest firmly against the pad, grasp handles, and pull back focusing on upper-back contraction.', 'Back', 1),
('Flat Dumbbell Fly', 'Lie on a flat bench, maintain a slight elbow bend, lower dumbbells out wide, and bring them together over chest.', 'Chest', 0),
('Cable Crossover', 'Set pulleys high, step forward into a staggered stance, and bring handles together in a wide hugging arc.', 'Chest', 1),
('Pec Deck Fly', 'Adjust seat so handles align with mid-chest, keep elbows slightly bent, and bring arms together in front.', 'Chest', 1),
('Push-Up', 'Place hands slightly wider than shoulders, keep body in a rigid plank, and lower chest until just above the floor.', 'Chest', 0),
('Overhead Barbell Press', 'Grip bar just outside shoulders, brace abs and glutes, and press barbell straight overhead until lockout.', 'Shoulders', 0),
('Dumbbell Lateral Raise', 'Hold dumbbells at sides with a slight elbow bend and raise arms out to shoulder height leading with elbows.', 'Shoulders', 0),
('Machine Shoulder Press', 'Adjust seat so handles sit at shoulder level, keep back against pad, and press overhead smoothly.', 'Shoulders', 1),
('Cable Face Pull', 'Set rope attachment at upper-chest height, pull toward forehead while externally rotating hands apart.', 'Shoulders', 1),
('Barbell Bicep Curl', 'Stand tall with elbows pinned to your sides, curl the bar up without swinging torso, and lower under control.', 'Biceps', 0),
('Incline Dumbbell Curl', 'Sit back on a 45-degree incline bench, let arms hang straight down, and curl dumbbells while keeping elbows back.', 'Biceps', 0),
('Preacher Curl Machine', 'Rest upper arms flat on the angled pad, grip handles, and curl upward without lifting elbows off the pad.', 'Biceps', 1),
('Cable Tricep Pushdown', 'Keep elbows tucked tight to your ribs, press the rope or bar down until arms are fully extended.', 'Triceps', 1),
('Overhead Dumbbell Tricep Extension', 'Hold one dumbbell with both hands overhead, lower behind your head by bending elbows, and extend back up.', 'Triceps', 0),
('Hanging Leg Raise', 'Hang from a pull-up bar, brace core, and raise straight or bent legs until thighs reach chest height.', 'Core', 0),
('Cable Crunch', 'Kneel below a high pulley holding a rope behind your head and curl ribs down toward your pelvis.', 'Core', 1);